import { useMemo } from 'react';

import { ChartLegendItem } from 'components/ChartLegend/ChartLegend';
import { LineBarChartsSectionData } from 'pages/pillars/ValueCreation/PerformanceTool/types';
import { getBarChartOptionsFromDatasets } from 'pages/pillars/ValueCreation/PerformanceTool/utils/getBarChartOptions';
import dataFoundations from 'theme/colors/dataFoundations';

export type LineBarChartColors = {
  lastYear: string;
  budget?: string;
  current: string;
};

export const DEFAULT_LINE_BAR_CHART_COLORS: LineBarChartColors = {
  lastYear: dataFoundations.charts.bg.series.lastYear,
  budget: dataFoundations.charts.bg.series.budget,
  current: dataFoundations.charts.bg.series.current,
};

const LABEL_TO_SERIES_KEY: Record<string, keyof LineBarChartColors> = {
  'last year': 'lastYear',
  ly: 'lastYear',
  budget: 'budget',
  bu: 'budget',
  current: 'current',
  'current year': 'current',
  ac: 'current',
};

const normalizeLabel = (label?: string): string =>
  label?.trim().toLowerCase() ?? '';

export const getSeriesColorByLabel = (
  label: string | undefined,
  chartColors: LineBarChartColors,
): string => {
  const seriesKey = LABEL_TO_SERIES_KEY[normalizeLabel(label)] ?? 'current';
  return chartColors[seriesKey] ?? chartColors.current;
};

export const isBudgetSeriesLabel = (label?: string): boolean => {
  const normalized = normalizeLabel(label);
  return normalized === 'budget' || normalized === 'bu';
};

const createColorHelpers = (chartColors: LineBarChartColors) => {
  const getColor = (label?: string): string =>
    getSeriesColorByLabel(label, chartColors);

  const getBarColors = (
    labels: string[],
    stripedIndexes: number[],
  ): string[] => {
    return labels.map((_, index, array) => {
      if (stripedIndexes.includes(index)) {
        return chartColors.budget ?? chartColors.current;
      }
      if (index === array.length - 1) return chartColors.current;
      return chartColors.lastYear;
    });
  };

  return { getColor, getBarColors };
};

export const useLineBarChartDatasets = (
  data?: LineBarChartsSectionData,
  chartColors: LineBarChartColors = DEFAULT_LINE_BAR_CHART_COLORS,
) => {
  const { getColor, getBarColors } = useMemo(
    () => createColorHelpers(chartColors),
    [chartColors],
  );

  const legendItems = useMemo<ChartLegendItem[]>(() => {
    if (!data?.legend) return [];
    return data.legend.map((item) => ({
      label: item.label,
      color: getColor(item.label),
      shape: 'rectangle',
      size: 'medium',
      decoration: isBudgetSeriesLabel(item.label) ? 'dash' : 'none',
    }));
  }, [data?.legend, getColor]);

  const lineDatasets = useMemo(() => {
    if (!data?.lineChart?.datasets) return [];
    return data.lineChart.datasets.map((dataset) => ({
      ...dataset,
      borderDash: dataset.label === 'Budget' ? [5, 5] : undefined,
      borderColor: getColor(dataset.label),
      pointBackgroundColor: getColor(dataset.label),
    }));
  }, [data?.lineChart?.datasets, getColor]);

  const barDatasets = useMemo(() => {
    if (!data?.barChart?.datasets) return [];
    const labels = data.barChart.labels || [];
    const backgroundColors = getBarColors(
      labels,
      data?.barChart?.stripedIndexes || [],
    );
    return data.barChart.datasets.map((dataset) => ({
      ...dataset,
      backgroundColor: backgroundColors,
    }));
  }, [
    data?.barChart?.datasets,
    data?.barChart?.labels,
    data?.barChart?.stripedIndexes,
    getBarColors,
  ]);

  const highlightedIndexes = useMemo(() => {
    return data?.lineChart?.highlightedIndexes || [];
  }, [data?.lineChart?.highlightedIndexes]);

  const barOptions = useMemo(
    () => getBarChartOptionsFromDatasets(data?.barChart?.datasets),
    [data?.barChart?.datasets],
  );

  return {
    legendItems,
    lineDatasets,
    barDatasets,
    highlightedIndexes,
    barOptions,
  };
};
